// constants
import Web3 from "web3";
import MarketPlace from "../../contracts/MarketPlace.json";
import nft from "../../contracts/NFT.json";

// log
import { fetchData } from "../data/dataActions";

const connectRequest = () => {
  return {
    type: "CONNECTION_REQUEST",
  };
};

const connectSuccess = (payload) => {
  return {
    type: "CONNECTION_SUCCESS",
    payload: payload,
  };
};

const connectFailed = (payload) => {
  return {
    type: "CONNECTION_FAILED",
    payload: payload,
  };
};

const updateAccountRequest = (payload) => {
  return {
    type: "UPDATE_ACCOUNT",
    payload: payload,
  };
};

export const connect = () => {
  return async (dispatch) => {
    dispatch(connectRequest());
    if (window.ethereum) {
      let web3 = new Web3(window.ethereum);
      try {
        const accounts = await window.ethereum.request({
          method: "eth_requestAccounts",
        });
        const networkId = await window.ethereum.request({
          method: "net_version",
        });
        const NetworkData1 = await MarketPlace.networks[networkId];
        const NetworkData2 = await nft.networks[networkId];
        if (NetworkData1 && NetworkData2) {
          const MarketPlaceObj = new web3.eth.Contract(
            MarketPlace.abi,
            NetworkData1.address
          );
          const nftObj = new web3.eth.Contract(
            nft.abi,
            NetworkData2.address
          );
          dispatch(
            connectSuccess({
              account: accounts[0],
              MarketPlace: MarketPlaceObj,
              nft: nftObj,
              web3: web3,
             
            })
          );
          // Add listeners start
          window.ethereum.on("accountsChanged", (accounts) => {
            dispatch(updateAccount(accounts[0]));
          });
          window.ethereum.on("chainChanged", () => {
            window.location.reload();
          });
          // Add listeners end
         
        } else {
          dispatch(connectFailed("Change network in Metamask."));
        }
      } catch (err) {
        dispatch(connectFailed("Something went wrong."));
      }
    } else {
      dispatch(connectFailed("Install Metamask."));
    }
  };
};

export const updateAccount = (account) => {
  return async (dispatch) => {
    dispatch(updateAccountRequest({ account: account }));
    dispatch(fetchData(account));
  };
};
